const $=s=>document.querySelector(s);let latest=null,file=null;const state={topic:null,entities:{},history:[]};
const rules={security:['忽略指令','system prompt','prompt injection','密碼','信用卡號','jailbreak'],return:['退貨','退款','退費','破損','瑕疵','買錯'],repair:['故障','壞掉','不能開機','異音','維修','過熱'],order:['訂單','出貨','到貨','物流','配送','包裹'],billing:['發票','刷卡','付款','扣款','分期','統編'],product:['庫存','規格','相容','推薦','多少錢','價格','有貨']};
const labels={product:'商品諮詢',order:'訂單查詢',return:'退貨退款',repair:'故障維修',billing:'付款發票',security:'安全事件',other:'範圍外或資訊不足'};
function classify(text,name,method){let combined=(text+' '+name).toLowerCase(),route='other',hits=[];for(const [r,ks] of Object.entries(rules)){let n=ks.filter(k=>combined.includes(k.toLowerCase())).length;if(n>hits.length){route=r;hits=ks.filter(k=>combined.includes(k.toLowerCase()))}}if(name&&!/\.(png|jpe?g|webp|gif)$/i.test(name)){route='security';hits=['unsupported_file_type']}if(method==='sft'&&text.includes('怎麼還沒來'))route='order';let id=text.match(/(?:訂單|order)[#：:\s-]*([A-Za-z0-9]{5,})/i);if(id)state.entities.order_id=id[1];let missing=(route==='order'&&!state.entities.order_id)?['order_id']:(route==='return'&&!state.entities.order_id)?['order_id']:[];let confidence=route==='other'?.48:Math.min(.98,.72+hits.length*.1);return{route,intent:labels[route],confidence:+confidence.toFixed(2),needs_clarification:route==='other'||missing.length>0,missing_fields:missing,entities:{...state.entities,...(name?{attachment:{name,type:'image'}}:{})},safety:{blocked:route==='security',signals:hits},method,demo_engine:true}}
function add(role,text,meta=''){let a=document.createElement('article');a.className=role;a.innerHTML=role==='bot'?'<div class="avatar">N</div><div class="bubble"></div>':'<div class="bubble"></div>';a.querySelector('.bubble').textContent=text;if(meta){let m=document.createElement('div');m.className='meta';m.textContent=meta;a.querySelector('.bubble').appendChild(m)}$('#messages').appendChild(a);$('#messages').scrollTop=$('#messages').scrollHeight}
function send(text=$('#input').value.trim()){if(!text&&!file)return;add('user',text||'（附加圖片）',file?'附件：'+file.name:'');$('#input').value='';$('#typing').hidden=false;setTimeout(()=>{let r=classify(text,file?.name||'',$('#method').value),msg;if(r.safety.blocked)msg='偵測到可能的提示注入或不安全檔案，已停止處理並轉交安全佇列。';else if(r.route==='other')msg='這似乎不是 3C 購物客服問題。你想詢問商品、訂單、退貨、維修，還是付款／發票？';else if(r.missing_fields.length)msg=`已辨識為「${r.intent}」，請再提供訂單編號以完成分流。`;else msg=`已確認為「${r.intent}」，案件已分流至 ${r.route} 處理佇列。`;if(state.topic&&state.topic!==r.route&&!['other','security'].includes(r.route))msg='看起來你開始了新的問題；上一個案件已保留。'+msg;if(!['other','security'].includes(r.route))state.topic=r.route;latest=r;state.history.push({text,r});add('bot',msg,`路由：${r.route} · 信心 ${r.confidence} · ${$('#method').selectedOptions[0].text}`);$('#typing').hidden=true;file=null;$('#preview').textContent=''},650)}
$('#send').onclick=()=>send();$('#input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}};$('#file').onchange=e=>{file=e.target.files[0]||null;$('#preview').textContent=file?`已選擇：${file.name} · ${(file.size/1024).toFixed(1)} KB`:''};document.querySelectorAll('.chips button').forEach(b=>b.onclick=()=>send(b.textContent));$('#reset').onclick=()=>location.reload();
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('nav button,.view').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#'+b.dataset.view+'View').classList.add('active');$('#viewTitle').textContent={chat:'3C 購物客服',results:'實驗結果',about:'系統架構'}[b.dataset.view]});
$('#jsonBtn').onclick=()=>{$('#jsonOutput').textContent=latest?JSON.stringify(latest,null,2):'尚無輸出';$('#jsonDialog').showModal()};$('#closeDialog').onclick=()=>$('#jsonDialog').close();
